using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

builder.Services.AddSingleton<ModelTrainingService>();

// Train the model at startup so the pool has a file to load
var trainingService = new ModelTrainingService(
    LoggerFactory.Create(b => b.AddConsole())
        .CreateLogger<ModelTrainingService>());
trainingService.TrainAndEvaluate();

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainingService.ModelPath);

// Load the model and schema so the controller can extract label slot names
var mlContext = new MLContext();
var model = mlContext.Model.Load(trainingService.ModelPath, out var schema);
builder.Services.AddSingleton(model);
builder.Services.AddSingleton(schema);

var app = builder.Build();
app.MapControllers();
app.Run();

